            "SELECT subject_key, purpose, epoch, record_key, payload FROM consent_record"
                    + " WHERE subject_key = ? AND purpose = ? AND epoch = ? ORDER BY record_key ASC",
            RECORD_MAPPER, subjectKey, purpose.name(), epoch);
}

