        write("w-3", "subj-a", "PERSONALIZATION", "rec-p", "p").andExpect(status().isOk());

        // 只请求 RESEARCH：只含当前 epoch=2 的记录，不混入旧代与 PERSONALIZATION
        export("e-1", "exp-1", "subj-a", "RESEARCH")
